out = "// Generated by scripts/gen-build-icons.py: every icon the build HUD and the tool presets name, imported by name so unused icons stay out of the bundle.\n"
out += "import { " + ", ".join(names) + ", type LucideIcon } from 'lucide-react';\n\n"
